// === Tab: mySketch ===
// ✨ Friday Vibe: Galactic Helix
// Vibe Coding by mindric lab
// Organic Noise Tunnel in Space

let t = 0;
let stars = [];

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 100);

  // Einmalig Sterne generieren
  for(let i=0; i<100; i++){
    stars.push({
      x: random(width), 
      y: random(height), 
      size: random(1, 3),
      alpha: random(50, 100)
    });
  }
}

function draw() {
  // 1. Background mit leichtem Fade für Schlieren
  background(0, 0, 0, 20);

  // 2. Sterne zeichnen (statisch im Hintergrund für Tiefe)
  noStroke();
  for(let s of stars){
    fill(200, 10, 100, s.alpha); // Weiß-bläuliche Sterne
    circle(s.x, s.y, s.size);
  }

  // 3. Der Helix-Tunnel (basierend auf deinem Favoriten V2)
  translate(width/2, height/2);
  noFill();
  strokeWeight(2);

  // Wir zeichnen 50 Ringe von außen nach innen
  for (let i = 0; i < 50; i++) {

    // Farbe: Verlauf von Deep Purple (260) zu Neon Blue (180)
    let hue = map(i, 0, 50, 260, 180);
    // Helligkeit pulsiert leicht
    let bright = 100;

    stroke(hue, 80, bright, 60); 

    push(); // Speichert aktuellen Zustand

    // Die Rotation macht es zur Spirale!
    // Äußere Ringe drehen sich anders als innere -> Sog-Effekt
    rotate(t * 0.2 + i * 0.05); 

    beginShape();
    // Der organische Kreis (Noise)
    for (let a = 0; a < TWO_PI; a += 0.1) {
      // Noise Koordinaten rotieren mit der Zeit
      let xoff = map(cos(a), -1, 1, 0, 3 + sin(t)*2);
      let yoff = map(sin(a), -1, 1, 0, 3 + cos(t)*2);

      // Radius wird durch Noise verzerrt -> "Flüssig"
      let noiseVal = noise(xoff, yoff, t * 0.5 + i * 0.05);
      // Basis-Radius hängt von i ab (Tunnel-Größe)
      let r = map(i, 0, 50, 10, 300) + map(noiseVal, 0, 1, -30, 30);

      let x = r * cos(a);
      let y = r * sin(a);
      vertex(x, y);
    }
    endShape(CLOSE);

    pop(); // Setzt Rotation zurück für nächsten Ring
  }

  // Zeit läuft
  t += 0.01;
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  // Sterne neu verteilen bei Resize
  stars = [];
  for(let i=0; i<100; i++){
    stars.push({x: random(width), y: random(height), size: random(1, 3), alpha: random(50, 100)});
  }
}

